 "content": "from functools import lru_cache

# The 8-cells are tiled by 2x2 squares (color 1) and four fixed
# orientations of 3-cell L pieces (colors 2-5). Each tile placement
# must be fully contained in the input 8-mask.
SHAPES = {
    1: ((0, 0), (0, 1), (1, 0), (1, 1)),
    2: ((0, 1), (1, 0), (1, 1)),  # missing upper-left
    3: ((0, 0), (0, 1), (1, 1)),  # missing lower-left
    4: ((0, 0), (1, 0), (1, 1)),  # missing upper-right
    5: ((0, 0), (0, 1), (1, 0)),  # missing lower-right
}


def transform(grid):
    rows, cols = len(grid), len(grid[0])
    cells = {(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == 8}
    placements = []
    for color, shape in SHAPES.items():
        max_r = rows - max(r for r, _ in shape)
        max_c = cols - max(c for _, c in shape)
        for r in range(max_r):
            for c in range(max_c):
                placed = tuple(sorted((r + dr, c + dc) for dr, dc in shape))
                if all(pos in cells for pos in placed):
                    placements.append((frozenset(placed), color))

    covering = {cell: [] for cell in cells}
    for piece, color in placements:
        for cell in piece:
            covering[cell].append((piece, color))

    @lru_cache(None)
    def solve(remaining):
        if not remaining:
            return ()
        rem = set(remaining)
        cell = min(rem, key=lambda x: sum(piece <= rem for piece, _ in covering[x]))
        for piece, color in covering[cell]:
            if piece <= rem:
                rest = solve(tuple(sorted(rem - piece)))
                if rest is not None:
                    return ((piece, color),) + rest
        return None

    result = solve(tuple(sorted(cells)))
    if result is None:
        raise ValueError("8-cells cannot be tiled by the known pieces")
    out = [[0] * cols for _ in range(rows)]
    for piece, color in result:
        for r, c in piece:
            out[r][c] = color
    return out


if __name__ == "__main__":
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
